// S5: consumidor idempotente. Se descarta lo que no cumple el sobre del contrato y lo que ya se procesó.
const datos = $getWorkflowStaticData('global');
datos.procesados = datos.procesados || [];
const RUTAS = {
  'ia.VisitanteRecurrenteDetectado': 0,
  'finanzas.PagoRegistrado': 1,
  'finanzas.PagoConfirmado': 2,
  'reservas.ReservaConfirmada': 3,
  'reservas.ReservaFallida': 4,
};
const salida = [];
for (const item of $input.all()) {
  const e = item.json;
  const valido = e && typeof e.eventId === 'string' && typeof e.type === 'string' && e.data && typeof e.data === 'object';
  if (!valido) continue;                              // mensaje ajeno al contrato
  if (datos.procesados.includes(e.eventId)) continue;  // ya avisado: un repetido no genera otro correo
  salida.push({ json: { ...e, ruta: e.type in RUTAS ? RUTAS[e.type] : 5 } });
}
return salida;

const hora = (iso) => new Date(iso).toLocaleString('es-BO', { timeZone: 'America/La_Paz', dateStyle: 'medium', timeStyle: 'short' });
// TODO(regla): el correo del residente debe salir de Gestión (GraphQL) cuando exponga los contactos por unidad.
// Mientras tanto: CONTACTOS_UNIDADES = {"<unidadId>": "correo"}; sin entrada, el aviso va al ADMIN.
const contacto = (unidadId) => {
  let mapa = {};
  try { mapa = JSON.parse($env.CONTACTOS_UNIDADES || '{}'); } catch (e) { mapa = {}; }
  return mapa[unidadId] || $env.ADMIN_EMAIL;
};
const e = $json;
const d = e.data;
// Sin fotos ni datos del rostro (I1, I6): solo cuántas veces y cuándo.
const camara = d.camara ? `\nCámara: ${d.camara}` : '';
return { json: { eventId: e.eventId, tipo: e.type, para: $env.GUARDIA_EMAIL,
  asunto: 'Visitante recurrente no registrado',
  texto: `Un visitante que no está registrado apareció ${d.apariciones} veces en ${d.diasDistintos} días distintos.\n` +
         `Primera vez: ${hora(d.primeraVez)}\nÚltima vez: ${hora(d.ultimaVez)}${camara}\n\n` +
         `Es una ayuda para el guardia: el sistema no abre ni bloquea a nadie por esto (A5).` } };

const hora = (iso) => new Date(iso).toLocaleString('es-BO', { timeZone: 'America/La_Paz', dateStyle: 'medium', timeStyle: 'short' });
// TODO(regla): el correo del residente debe salir de Gestión (GraphQL) cuando exponga los contactos por unidad.
