};
const e = $json;
const d = e.data;
const extra = [d.banco ? `Banco: ${d.banco}` : '', d.nroOperacion ? `Operación: ${d.nroOperacion}` : ''].filter(Boolean).join('\n');
return { json: { eventId: e.eventId, tipo: e.type, para: $env.ADMIN_EMAIL,
  asunto: 'Pago pendiente de conciliación',
  texto: `Un residente registró un pago que espera su revisión.\n\nUnidad: ${d.unidadId}\nMonto: ${d.monto}\n` +
         `Fecha del comprobante: ${d.fechaPago}${extra ? '\n' + extra : ''}\n\n` +
         `El pago sigue PENDIENTE hasta que el ADMIN lo confirme en la consola (F8, F9).` } };

