// Solo se marca como procesado después de enviar el correo: si falló, el reintento manual no se confunde con un repetido.
const datos = $getWorkflowStaticData('global');
datos.procesados = datos.procesados || [];
const id = $('Interpretar y evitar duplicados').item.json.eventId;
if (!datos.procesados.includes(id)) datos.procesados.push(id);
if (datos.procesados.length > 500) datos.procesados = datos.procesados.slice(-500);
return { json: { eventId: id, enviado: true } };
